const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['志工是會員嗎','志工和會員是兩回事'],['志工是不是會員','志工和會員是兩回事'],['志工算不算協會會員','志工和會員是兩回事'],['志工算會員嗎','志工和會員是兩回事'],
['志工的名冊可以公開嗎','志工的名冊和個人資料'],['志工名單可以貼上網嗎','志工的名冊和個人資料'],['志工資料能給別人嗎','志工的名冊和個人資料'],
['志工能當會計嗎','財務人員要專任'],['可以讓志工管錢當出納嗎','財務人員要專任'],['志工可不可以擔任財務','財務人員要專任'],
['志工有補助嗎','運用單位必要時可補助交通、誤餐'],['志工有沒有經費可以申請','運用單位必要時可補助交通、誤餐'],['志工會有津貼嗎','運用單位必要時可補助交通、誤餐'],
];
const no=['發志工津貼要報稅嗎','志工是會員嗎要繳會費嗎','志工要不要加入會員','志工一定要是會員嗎','志工可以領錢嗎','志工有車馬費嗎','志工要保險嗎','志工服務時數怎麼算','志工要不要受訓','志工獎勵怎麼申請','志工隊要向誰報備','協會會員名冊可以公開嗎','理事長可以當會計嗎','協會會計要專任嗎','協會有補助嗎','合作社志工是社員嗎','社區發展協會志工補助','志工受傷怎麼辦','會員可以不當志工嗎還能退會嗎','志工榮譽卡怎麼辦'];
const pat=/志工和會員是兩回事|志工的隱私應受尊重|志工的名冊和個人資料|財務人員要專任|運用單位必要時可補助交通、誤餐/;
let bad=0;
for(const [q,k] of yes){const x=A(q);if(!x||!x.direct||!(x.summary+x.title).includes(k)){console.error('FAIL',q,x&&x.title);bad++;}}
for(const q of no){const x=A(q);if(x&&typeof x==='object'&&pat.test(x.title)){console.error('OVERTRIGGER',q,x.title);bad++;}}
if(bad)throw new Error('patrol65 failed '+bad);console.log('ok');
